  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Calculate the final trip price for a customer after applying discount rewards when eligible.
   * Algorithm:
   * 1. If customer is null or bookingTime is null, return price.
   * 2. If customer.membershipPackage is null, return price.
   * 3. If customer.membershipPackage does not contain Award.DISCOUNTS, return price.
   * 4. If booking time is less than 24 hours before departure, return price.
   * 5. Compute discounted = price * 0.8.
   * 6. Round to one decimal place and return the rounded value.
   * Related Features:
   * - price
   * - departureDate
   * - departureTime
   * - calculateDiscountedPrice(customer, bookingTime)
   * Related Classes: Customer, MembershipPackage, Award, EDate
   * Input:
   * - customer: Customer, booking customer.
   * - bookingTime: String, booking timestamp, comparable with trip departure date/time.
   * Output:
   * - double.
   * - Final trip price.
   * - Discounted result is rounded to one decimal place.
   * Pre-condition:
   * - Trip price is defined.
   * - Departure date/time and bookingTime are parseable for time comparison.
   * Post-condition:
   * - No state is modified.
   * - Returns discounted price only when the DISCOUNTS award and 24-hour rule are satisfied.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public double calculateDiscountedPrice(final Customer customer, final String bookingTime)
  {
    if (customer == null || bookingTime == null)
    {
      return price;
    }
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.DISCOUNTS))
    {
      return price;
    }
    if (departureDate == null || departureTime == null)
    {
      return price;
    }
    try
    {
      java.text.SimpleDateFormat df = new java.text.SimpleDateFormat("yyyy-MM-dd HH:mm");
      java.util.Date dep = df.parse(new java.text.SimpleDateFormat("yyyy-MM-dd").format(departureDate) + " " + departureTime);
      java.util.Date book = df.parse(bookingTime);
      long diffMillis = dep.getTime() - book.getTime();
      if (diffMillis < 24L * 60L * 60L * 1000L)
      {
        return price;
      }
      double discounted = price * 0.8;
      return Math.round(discounted * 10.0) / 10.0;
    }
    catch (Exception e)
    {
      return price;
    }
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary:
   * Calculate reward points for a customer for bookings on this trip within a given month.
   * Algorithm:
   * 1. Return 0 if customer is null or currentMonth is null.
   * 2. Return 0 if customer.membershipPackage is null or does not contain Award.POINTS.
   * 3. Initialize totalPoints = 0.
   * 4. For each booking in bookings:
   *    - if booking.customer equals the given customer and booking.isInMonth(currentMonth) is true:
   *      totalPoints += booking.numberOfSeats * 5
   * 5. Return totalPoints.
   * Related Features:
   * - bookings
   * - price
   * - calculateMonthlyPoints(customer, currentMonth)
   * Related Classes: Customer, Booking, MembershipPackage, Award
   * Input:
   * - customer: Customer, target customer.
   * - currentMonth: String, month identifier, typically "YYYY-MM".
   * Output:
   * - int.
   * - Total points earned from this trip in that month.
   * Pre-condition:
   * - Trip and customer exist.
   * - Booking records may be empty.
   * Post-condition:
   * - No state is modified.
   * - Returns the month-specific reward points for the customer on this trip.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public int calculateMonthlyPoints(final Customer customer, final String currentMonth)
  {
    if (customer == null || currentMonth == null)
    {
      return 0;
    }
    MembershipPackage membershipPackage = customer.getMembershipPackage();
    if (membershipPackage == null || !membershipPackage.hasAward(Award.POINTS))
    {
      return 0;
    }
    int totalPoints = 0;
    if (bookings != null)
    {
      for (Booking booking : bookings)
      {
        if (booking != null && customer.equals(booking.getCustomer()) && booking.isInMonth(currentMonth))
        {
          totalPoints += booking.getNumberOfSeats() * 5;
        }
      }
    }
    return totalPoints;
  }

